"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["529"],{2668(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"reference/monitor/howtos/systemBulkActivate","title":"How to launch a bulk activation?","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/systemBulkActivate.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/systemBulkActivate","permalink":"/personal-av-docs/docs/reference/monitor/howtos/systemBulkActivate","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/systemBulkActivate.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to launch a bulk activation?","sidebar_label":"How to launch a bulk activation?","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/monitor/howtos/systemBulkActivate","format":"md"}}'),i=o(4848),a=o(8453);let s={title:"How to launch a bulk activation?",sidebar_label:"How to launch a bulk activation?",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/monitor/howtos/systemBulkActivate",format:"md"},r,l={},c=[];function h(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/reference/monitor/howtos/systemBulkActivate",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"How to launch a bulk activation?\nIf you have only a few new SIMs/systems to Activate, you can simply do so from the connectivity management portal by selecting the SIMs and then clicking the \u2018Activate\u2019 button.\nIf you have a larger number of SIMs to activate you may need to use one of the following techniques:\nInitializing Table Of Contents...\nUse filters to select SIMs to activate\nIf you have a large number of SIMs to activate - hundreds or even thousands - you will find it useful to apply single or multiple filters to the list before selecting the SIMs to activate.\nThe first useful filter to consider is the\nState\none, as you can only activate SIMs that are in the Inventory state of the lifecycle. To filter the SIM list to show only these SIMS, simply click the Inventory segment on the State chart. This applies a State = Inventory filter, as shown below.\nYou can also add a filter based on\nLabel\nin the grid. Multiple filters can be applied on the fleet: filter on state + with a specific label for example.\nAnother useful filter is the one on\nICCID\n. You can select all ICCIDs that start with a specific pattern. In this example, the filter will match all SIMs whose ICCID series starts with these 13 digits:\nActivate all SIMs from a specific order\nOne common use case it when you need to activate all the SIMs from a given order. This can be done by filtering the list down to those SIMs matching a given Order ID.\nFirst display the\nMonitor\nsection of your Connectivity Portal. Use the filter bar, select filter on\nOrder ID\nand then provide as input the orderID you are looking for. The orderID is starting in \u2018SO-\u2019 (SIM Order) and can be displayed by adding the column\nOrder ID\nto your grid, as shown below:\nOnce you have filtered the SIMs/Systems with a specific Order-ID, you just have to select all SIMs from this list by selecting the top checkbox, then click on\nActivate\n. As an alternative to selecting all SIMs you can also choose only one or more among the filtered selection.\nOnce launched the status of the Activate operation can be checked as usual in the Operations list.\nExport SIM data for advanced selection and activation\nSometimes you may wish to apply more sophisticated sorting and/or filtering to a list of SIMs, in order to correctly identify those you wish to activate. You can use the\nExport data\noption to create a CSV file that you can then edit in a tool such as Excel.\nFirst select the range of SIMs whose data you want to export. For example all those corresponding to a give Order, or taggged with a custom Label. Then select\nMore\n>\nExport Data\n, and specify the fields to include in the CSV file. Watch how:\nYou can retrieve and export the CSV file from the Operations screen. Select\nActions\n>\nView\nfor the completed Export System(s) data operation, click the link to retrieve the CSV file, then Open or Save it. Watch how:\nNow you can import it into Excel or a similar tool. For example, open a new workbook in Excel and select the File > From Text icon, which launches the Text file Import Wizard.\nSelect the CSV file you saved\nSpecify that it is comma-delimited\nData in some columns will be imported better if you specify that it should be in Text format rather than Number (for Subscription IDs, for example)\nWatch how:\nSuppose we now want to Sort this - for instance, on the Subscription ID column. Use the Excel Sort tool.\nYou can of course define more complex multi-column Sorts, and/or Filters in Excel, to apply to your data.\nOnce you have identified the list of SIMs you want to activate, in AirVantage, you can apply a label to those SIMs to further take action on this selection.  Let\u2019s take as an example, some SIMs that we have identified from a Sort operation in Excel.\nIn AirVantage, select the\nChange Labels\naction.\nSelect the field to be filtered by the new Label, most likely ICCID/ESN, then simply do a Copy/Paste from your selection in Excel into the list field.\nYou can now apply the Label by Adding a Label filter and typing part or all its name\u2026\nHere we have applied the new Label Filter, you can use the check box at the top left of the list to select all SIMs/systems with the created label. Once done, you are ready, now simply click on Activate!\nFollow activation progress\nOnce you launched activation on the offer of choice, you can follow the progress of the activation as any other operation in the Operation widget. If a large number of systems has been selected, this may operation take some time to complete (typically a few minutes per SIM).\nYou can click on the operation details to view the status per SIM:"})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},8453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var n=o(6540);let i={},a=n.createContext(i);function s(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);